  Widget _buildActiveOrderBanner(BuildContext context, JeebliController controller) {
    final statusLabel = {
      OrderStatus.confirmed: '✅ تم تأكيد طلبك',
      OrderStatus.preparing: '👨‍🍳 جاري تحضير وجبتك',
      OrderStatus.onWay: '🛵 المندوب في الطريق',
      OrderStatus.arrived: '🎉 وصل المندوب!',
    }[controller.orderStatus] ?? '';

    final minutes = controller.deliveryCountdown ~/ 60;
    final seconds = controller.deliveryCountdown % 60;

    return GestureDetector(
      onTap: () {
        Navigator.push(context, MaterialPageRoute(
          builder: (_) => const Directionality(textDirection: TextDirection.rtl, child: LiveTrackingScreen()),
        ));
      },
      child: Container(
        margin: const EdgeInsets.only(bottom: 12),
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          gradient: const LinearGradient(colors: [Color(0xFFE65100), Color(0xFFFFB300)], begin: Alignment.topRight, end: Alignment.bottomLeft),
          borderRadius: BorderRadius.circular(16),
        ),
        child: Row(
          children: [
            const Icon(Icons.delivery_dining, color: Colors.white, size: 28),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(statusLabel, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 13)),
                  if (controller.deliveryCountdown > 0)
                    Text('الوقت المتبقي: ${minutes.toString().padLeft(2, '0')}:${seconds.toString().padLeft(2, '0')}',
                        style: const TextStyle(color: Colors.white70, fontSize: 11)),
                ],
              ),
            ),
            const Icon(Icons.arrow_forward_ios, color: Colors.white, size: 14),
          ],
        ),
      ),
    );
  }
}

